import React from 'react';
import {
  ProgressTrackerContextProps,
  useProgressTrackerContext,
} from '../../../../ProgressTrackerContext';
import { ProgressTrackerContentItemProps } from './ProgressTrackerContentItem.types';

const ProgressTrackerContentItem = ({
  index,
  children,
}: ProgressTrackerContentItemProps): JSX.Element => {
  const { currentStep } = useProgressTrackerContext() as ProgressTrackerContextProps;
  return currentStep === index ? <>{children}</> : <></>;
};

export default ProgressTrackerContentItem;
